31	    private static IEnumerable<Cita> Condicionales(IReadOnlyList<ResumenEstudiante> resumenes)
32	    {
33	        var resultados = resumenes.SelectMany(resumen => resumen.Asignaturas).ToList();
34	        if (resultados.Any(r => r.Estado == EstadoAsignatura.Perdida))
35	        {
36	            yield return NotaMinima;
37	            yield return Habilitacion;
38	        }
39	
40	        if (resultados.Any(r => r.Estado == EstadoAsignatura.PerdidaPorInasistencia))
41	        {
42	            yield return NoHabilitables;
43	            yield return PerdidaPorInasistencia;
44	        }
45	
46	        foreach (var cita in CondicionalesDeEstado(resumenes, resultados))
47	        {
48	            yield return cita;
49	        }
50	    }
