52	    private static IEnumerable<Cita> CondicionalesDeEstado(IReadOnlyList<ResumenEstudiante> resumenes, List<ResultadoAsignatura> resultados)
53	    {
54	        if (resumenes.Any(resumen => resumen.PruebaAcademica))
55	        {
56	            yield return PruebaAcademica;
57	        }
58	
59	        if (resultados.Any(r => r.EstadoAsistencia == EstadoAsistencia.SinRegistro))
60	        {
61	            yield return AsistenciaSinRegistro;
62	        }
63	
64	        if (resultados.Any(r => r.Estado == EstadoAsignatura.SinDefinitiva))
65	        {
66	            yield return DefinitivaEvaluacion;
67	        }
68	    }
69	}
